<?= $this->extend('layouts/main') ?>

<?= $this->section('content') ?>
<section class="directory-header shell pos-header"><div><span class="eyebrow">Catalog / Product detail</span><h1><?= esc($product['name']) ?></h1><p><?= esc($product['sku'] ?: 'No SKU assigned') ?> · Added <?= esc(date('M j, Y', strtotime($product['created_at']))) ?></p></div><div class="directory-actions"><a class="button secondary" href="<?= site_url('products') ?>">Back to inventory</a><?php if ($canManage && $product['is_active']): ?><a class="button primary" href="<?= site_url('products/' . $product['id'] . '/edit') ?>">Edit product</a><?php endif; ?></div></section>
<section class="shell detail-grid">
    <article class="panel detail-card"><img class="detail-product-image" src="<?= esc(! empty($product['image']) ? (str_starts_with((string) $product['image'], 'assets/') ? base_url($product['image']) : base_url('uploads/' . $product['image'])) : base_url('assets/images/product-placeholder.svg'), 'attr') ?>" alt="<?= esc($product['name'], 'attr') ?>"><div class="detail-copy"><span class="status-pill <?= $product['is_active'] ? ((int) $product['stock_quantity'] <= (int) $product['low_stock_threshold'] ? 'low' : 'active') : 'archived' ?>"><i></i><?= $product['is_active'] ? 'Active catalog item' : 'Archived' ?></span><p><?= nl2br(esc($product['description'] ?: 'No description provided.')) ?></p><dl class="detail-facts"><div><dt>SKU</dt><dd><?= esc($product['sku'] ?: 'Not assigned') ?></dd></div><div><dt>Price</dt><dd>₱<?= esc(number_format((float) $product['price'], 2)) ?></dd></div><div><dt>On-hand stock</dt><dd><?= esc((string) $product['stock_quantity']) ?> units</dd></div><div><dt>Alert threshold</dt><dd><?= esc((string) $product['low_stock_threshold']) ?> units</dd></div><div><dt>Added to catalog</dt><dd><?= esc(date('M j, Y', strtotime($product['created_at']))) ?></dd></div></dl><?php if (str_contains((string) ($product['description'] ?? ''), 'SAMPLE CATALOG ITEM')): ?><p class="sample-data-note"><strong>Sample catalog item:</strong> verify specifications, price, and stock count before using this item for real retail sales.</p><?php endif; ?></div></article>
    <aside class="panel detail-side"><span class="eyebrow">Recent activity</span><h2>Sales for this item</h2><?php if ($sales === []): ?><p class="muted-copy">No sales have been recorded for this product yet.</p><?php else: ?><ul class="activity-list"><?php foreach ($sales as $sale): ?><li><span>#<?= esc((string) $sale['id']) ?> · <?= esc(date('M j, Y', strtotime($sale['created_at']))) ?></span><strong><?= esc((string) $sale['quantity']) ?> × ₱<?= esc(number_format((float) $sale['unit_price'], 2)) ?></strong><small><?= esc($sale['customer_name'] ?: 'Walk-in customer') ?></small></li><?php endforeach; ?></ul><?php endif; ?><?php if ($canManage && $product['is_active']): ?><form class="archive-form" method="post" action="<?= site_url('products/' . $product['id'] . '/archive') ?>" data-confirm="Archive this product? Past receipts will remain available. The product must have zero stock."><?= csrf_field() ?><button class="button danger" type="submit">Archive product</button></form><?php elseif ($canManage): ?><form class="archive-form" method="post" action="<?= site_url('products/' . $product['id'] . '/restore') ?>"><?= csrf_field() ?><button class="button secondary" type="submit">Restore product</button></form><?php endif; ?></aside>
</section>
<?= $this->endSection() ?>
